//! An object's `<skeleton>` bakes to polylines with a radius at each
//! vertex, meshed as frustums.
//!
//! `skeleton.xodr` is generated by `scenariogeneration` (see `skeleton.py`).
//! Its road 1 is a straight from the origin heading +X at elevation
//! `1 + 0.02 s`, so the road surface at `(s, t)` is `(s, t, 1 + 0.02 s)`.

use xodr::{
    load_file, load_file_with_provenance, Extent, Object, Point, RoadNetwork, Shape,
    SkeletonVertex, Vector, Warning,
};

const FIXTURE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data/skeleton.xodr");

fn net() -> RoadNetwork {
    load_file(FIXTURE).expect("import")
}

fn surface(s: f32, t: f32) -> Point {
    Point::new(s, t, 1.0 + 0.02 * s)
}

fn named<'a>(net: &'a RoadNetwork, name: &str) -> Vec<&'a Object> {
    net.objects().iter().filter(|o| o.name == name).collect()
}

fn lines(object: &Object) -> &[Vec<SkeletonVertex>] {
    match &object.shape {
        Shape::Skeleton { lines } => lines,
        other => panic!("{} is not a skeleton: {other:?}", object.name),
    }
}

/// That `line` has vertices at `want`, each `(position, radius, ground)`.
fn assert_line(line: &[SkeletonVertex], want: &[(Point, f32, bool)], what: &str) {
    assert_eq!(line.len(), want.len(), "{what}: {line:?}");
    for (got, &(position, radius, ground)) in line.iter().zip(want) {
        assert!(
            (got.position - position).length() < 1e-4,
            "{what}: {:?}, expected {position:?}",
            got.position
        );
        assert_eq!((got.radius, got.ground), (radius, ground), "{what}");
    }
}

#[test]
fn a_skeleton_in_road_coordinates_replaces_the_bounding_box() {
    let net = net();
    let [light, _] = named(&net, "Light")[..] else {
        panic!("the light and its reference");
    };
    let [pole, arm] = lines(light) else {
        panic!("two polylines: {:?}", light.shape);
    };
    let up = |s, t, dz| surface(s, t) + Vector::Z * dz;
    assert_line(
        pole,
        &[
            (up(25.0, -4.0, 0.0), 0.15, true),
            (up(25.0, -4.0, 4.0), 0.1, false),
        ],
        "pole",
    );
    assert_line(
        arm,
        &[
            (up(25.0, -4.0, 3.0), 0.15, false),
            (up(25.0, -2.5, 3.25), 0.15, false),
            (up(25.0, 0.0, 3.25), 0.15, false),
        ],
        "arm",
    );
}

#[test]
fn a_skeleton_in_local_coordinates_turns_with_the_object() {
    let net = net();
    let [tree] = named(&net, "Tree")[..] else {
        panic!("one tree");
    };
    let [trunk] = lines(tree) else {
        panic!("one polyline: {:?}", tree.shape);
    };
    let (sin, cos) = 0.5_f32.sin_cos();
    let (u, v) = (-0.2, 1.0);
    let at = |z: f32| surface(10.0, 5.0) + Vector::new(u * cos - v * sin, u * sin + v * cos, z);
    assert_line(
        trunk,
        &[(at(1.12), 0.15, true), (at(4.5), 0.12, false)],
        "trunk",
    );
}

/// The `<object id>` of each `SkeletonDropped` warning.
fn dropped() -> Vec<String> {
    let (_, provenance) = load_file_with_provenance(FIXTURE).expect("import");
    provenance
        .warnings
        .into_iter()
        .filter_map(|w| match w {
            Warning::SkeletonDropped { object_id, .. } => Some(object_id),
            _ => None,
        })
        .collect()
}

#[test]
fn a_polyline_of_one_vertex_is_dropped_with_a_warning() {
    let net = net();
    let [stub] = named(&net, "Stub")[..] else {
        panic!("one stub");
    };
    assert_eq!(lines(stub).len(), 1);
    assert!(dropped().contains(&"3".to_string()), "{:?}", dropped());
}

#[test]
fn an_object_whose_skeleton_cannot_be_placed_keeps_its_box() {
    let net = net();
    let [off] = named(&net, "Off")[..] else {
        panic!("one off");
    };
    let Shape::Solid {
        extent: Some(Extent::Cylinder { radius, height }),
        ..
    } = off.shape
    else {
        panic!("a cylinder: {:?}", off.shape);
    };
    assert_eq!((radius, height), (0.2, 3.0));
    assert_eq!(dropped(), ["3", "4"]);
}

#[test]
fn a_repeat_moves_the_skeleton_to_each_step() {
    let net = net();
    let posts = named(&net, "Post");
    assert_eq!(posts.len(), 3);
    for (post, s) in posts.iter().zip([30.0, 40.0, 50.0]) {
        let [line] = lines(post) else {
            panic!("one polyline");
        };
        let foot = surface(s, 6.0);
        assert_line(
            line,
            &[(foot, 0.1, true), (foot + Vector::Z, 0.05, false)],
            "post",
        );
    }
}

#[test]
fn each_segment_meshes_as_a_capped_frustum_round_its_axis() {
    let net = net();
    let mesh = net.object_mesh();
    let light = named(&net, "Light")[0];
    let span = mesh
        .objects
        .iter()
        .find(|s| s.object == light.id)
        .expect("the light is meshed");
    let triangles = (span.indices.end - span.indices.start) / 3;
    // Three segments of 16 quads, and four caps of 14 triangles.
    assert_eq!(triangles, 3 * 16 * 2 + 4 * 14);
    let [pole, _] = lines(light) else {
        panic!("two polylines");
    };
    let (foot, top) = (pole[0].position, pole[1].position);
    let axis = (top - foot).normalize_or_zero();
    let vertices = &mesh.vertices[span.vertices.start as usize..span.vertices.end as usize];
    let normals = &mesh.normals[span.vertices.start as usize..span.vertices.end as usize];
    let mut sides = 0;
    for (p, n) in vertices.iter().zip(normals) {
        let along = (*p - foot).dot(axis);
        let radial = (*p - foot) - axis * along;
        if along.abs() < 1e-4 && n.dot(axis).abs() < 0.5 {
            assert!((radial.length() - 0.15).abs() < 1e-4, "{p:?} at the foot");
            assert!(n.dot(radial) > 0.0, "{n:?} faces in at {p:?}");
            sides += 1;
        }
    }
    assert!(sides >= 16, "{sides} side vertices at the foot");
}

#[test]
fn a_reference_moves_a_road_coordinate_skeleton_with_it() {
    let net = net();
    let [_, moved] = named(&net, "Light")[..] else {
        panic!("the light and its reference");
    };
    let [pole, _] = lines(moved) else {
        panic!("two polylines: {:?}", moved.shape);
    };
    let up = |s, t, dz| surface(s, t) + Vector::Z * dz;
    assert_line(
        pole,
        &[
            (up(45.0, -5.0, 0.0), 0.15, true),
            (up(45.0, -5.0, 4.0), 0.1, false),
        ],
        "moved pole",
    );
}

#[test]
fn a_double_cone_meshes_two_frustums_wound_outward() {
    let net = net();
    let mesh = net.object_mesh();
    let cone = named(&net, "Cone")[0];
    let radii: Vec<f32> = lines(cone)[0].iter().map(|v| v.radius).collect();
    assert_eq!(radii, [0.0, 0.0, 0.3, 0.0], "a negative radius reads as 0");
    let span = mesh
        .objects
        .iter()
        .find(|s| s.object == cone.id)
        .expect("the cone is meshed");
    // Two frustums of 16 quads, each with half its triangles at a point,
    // and no area in the caps at the two points.
    assert_eq!((span.indices.end - span.indices.start) / 3, 16 + 16);
    for light in named(&net, "Light").into_iter().chain([cone]) {
        let span = mesh.objects.iter().find(|s| s.object == light.id).unwrap();
        for tri in mesh.indices[span.indices.start as usize..span.indices.end as usize].chunks(3) {
            let [a, b, c] = [tri[0], tri[1], tri[2]].map(|i| i as usize);
            let (p, q, r) = (mesh.vertices[a], mesh.vertices[b], mesh.vertices[c]);
            let n = (q - p).cross(r - p);
            assert!(
                n.dot(mesh.normals[a]) > 0.0,
                "{} wound against its normal",
                light.name
            );
        }
    }
}
